    opts = {
        "format": "markdown",
        "to": "HEAD",
        "config": ".clog.toml",
        "link_style": "github",
        "major": False,
        "minor": False,
        "patch": False,
        "from_latest_tag": False,
    }
    seen = set()
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--help":
            return "help", opts
        if arg == "--version":
            return "version", opts
        if arg == "--":
            if i + 1 < len(argv):
                clap_usage_error(f"unexpected argument '{argv[i+1]}' found")
            i += 1
            continue
