    try:
        action, opts = parse_args(argv)
    except CliError as e:
        eprint(str(e))
        return e.code
    if action == "help":
        sys.stdout.write(HELP)
        return 0
    if action == "version":
        sys.stdout.write(VERSION)
        return 0

    try:
        cfg = parse_config(opts.get("config", ".clog.toml"))
    except ValueError:
        return app_error("Failed to parse TOML configuration file")
    except RuntimeError as e:
        return app_error(str(e))

    # Automatic version bumps fail in the observed binary unless an explicit setversion is present.
    if (opts.get("major") or opts.get("minor") or opts.get("patch")) and "setversion" not in opts:
        return app_error("Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.")

    # Config's changelog is a paired default input/output path. CLI infile/outfile override their side.
    cfg_changelog = cfg.get("changelog") if isinstance(cfg.get("changelog"), str) else None
    infile = opts.get("infile") if "infile" in opts else (cfg.get("infile") if isinstance(cfg.get("infile"), str) else cfg_changelog)
    outfile = opts.get("outfile") if "outfile" in opts else (cfg.get("outfile") if isinstance(cfg.get("outfile"), str) else cfg_changelog)
    if "changelog" in opts:
        infile = opts["changelog"]
        outfile = opts["changelog"]

    version = opts.get("setversion")
    subtitle = opts.get("subtitle") if "subtitle" in opts else None
    full = bool(outfile or infile)
    content = build_content(opts.get("format", "markdown"), version, subtitle, full)
    if infile:
        content += read_optional(infile)

    if outfile:
        try:
            with open(outfile, "w", encoding="utf-8") as f:
                f.write(content)
        except Exception:
            return app_error("fatal I/O error with output file")
    else:
        sys.stdout.write(content)

    elapsed = int((time.monotonic() - start) * 1000)
    if elapsed < 2:
        elapsed = 2
    sys.stdout.write(f"changelog written. (took {elapsed} ms)\n")
    return 0

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
