    }
    seen = set()
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--help":
            return "help", opts
        if arg == "--version":
            return "version", opts
        if arg == "--":
            if i + 1 < len(argv):
                clap_usage_error(f"unexpected argument '{argv[i+1]}' found")
            i += 1
            continue
        if arg.startswith("--"):
            name, eq, val = arg.partition("=")
            if name in VALUE_OPTS:
                key, ph = VALUE_OPTS[name]
                if eq:
                    value = val
                else:
                    if i + 1 >= len(argv):
                        value_required(name, ph)
                    if argv[i+1].startswith("-"):
                        # Clap reports the following token as an unexpected argument in common cases.
                        nxt = argv[i+1]
                        if nxt in ("--help", "-h"):
                            return "help", opts
                        if nxt in ("--version", "-V"):
                            return "version", opts
                        clap_usage_error(f"unexpected argument '{nxt}' found")
                    i += 1
                    value = argv[i]
                set_value(opts, seen, key, value)
            elif name in FLAG_OPTS and not eq:
                set_flag(opts, FLAG_OPTS[name])
            else:
                clap_usage_error(f"unexpected argument '{arg}' found")
        elif arg.startswith("-") and arg != "-":
            cluster = arg[1:]
            j = 0
            while j < len(cluster):
                ch = cluster[j]
                if ch == "h":
                    return "help", opts
                if ch == "V":
                    return "version", opts
                if ch in SHORT_FLAG:
                    set_flag(opts, FLAG_OPTS[SHORT_FLAG[ch]])
                    j += 1
                    continue
                if ch in SHORT_VALUE:
                    long = SHORT_VALUE[ch]
                    key, ph = VALUE_OPTS[long]
                    rest = cluster[j+1:]
                    if rest:
                        value = rest
                    else:
                        if i + 1 >= len(argv):
                            value_required(long, ph)
                        if argv[i+1].startswith("-"):
                            nxt = argv[i+1]
                            if nxt in ("--help", "-h"):
                                return "help", opts
                            if nxt in ("--version", "-V"):
                                return "version", opts
                            clap_usage_error(f"unexpected argument '{nxt}' found")
                        i += 1
                        value = argv[i]
                    set_value(opts, seen, key, value)
                    break
                clap_usage_error(f"unexpected argument '-{ch}' found")
        else:
            clap_usage_error(f"unexpected argument '{arg}' found")
        i += 1

    if opts.get("format") not in ("markdown", "json"):
        invalid_value("--format", opts.get("format"), ["markdown", "json"])
    if opts.get("link_style") not in ("github", "gitlab", "stash", "cgit"):
        invalid_value("--link-style", opts.get("link_style"), ["github", "gitlab", "stash", "cgit"])
    if "outfile" in opts and "changelog" in opts:
        clap_usage_error("the argument '--outfile <PATH>' cannot be used with '--changelog <PATH>'", "Usage: executable --outfile <PATH>")
    if "infile" in opts and "changelog" in opts:
        clap_usage_error("the argument '--infile <PATH>' cannot be used with '--changelog <PATH>'", "Usage: executable --infile <PATH>")
    return "run", opts

def app_error(msg):
    eprint("\x1b[1;31merror:\x1b[0m " + msg + "\n")
    return 1

def parse_config(path):
    try:
        data = open(path, "r", encoding="utf-8").read().splitlines()
    except Exception:
        raise RuntimeError("fatal I/O error with output file")
    section = None
    saw_clog = False
    vals = {}
    for raw in data:
        # trim comments conservatively, enough for observed TOML files
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("["):
            if not line.endswith("]") or line.count("[") != 1 or line.count("]") != 1:
                raise ValueError("Failed to parse TOML configuration file")
            section = line[1:-1].strip()
            if section == "clog":
                saw_clog = True
            continue
        if section == "clog":
            if "=" not in line:
                raise ValueError("Failed to parse TOML configuration file")
            k, v = line.split("=", 1)
            k = k.strip()
            v = v.strip()
            if not k:
                raise ValueError("Failed to parse TOML configuration file")
            if v.startswith('"') and v.endswith('"') and len(v) >= 2:
                vals[k] = v[1:-1]
            elif v in ("true", "false"):
                vals[k] = (v == "true")
            elif v:
                vals[k] = v
            else:
                raise ValueError("Failed to parse TOML configuration file")
        else:
            # top-level assignments / unknown sections made observed configs invalid.
            if "=" in line:
                raise ValueError("Failed to parse TOML configuration file")
    if not saw_clog:
        raise ValueError("Failed to parse TOML configuration file")
    return vals

def read_optional(path):
    if not path:
        return ""
    try:
        with open(path, "r", encoding="utf-8") as f:
            return f.read()
    except Exception:
        return ""

def markdown_header(version, subtitle, d, full):
    v = version or ""
    s = subtitle or ""
    out = f'<a name="{v}"></a>\n## {v} {s} ({d})'
    if full:
        return out + "\n\n\n\n\n"
    return out + "\n\n"

def json_header(version, subtitle, d, full):
    if version is None:
        v = "None"
    else:
        v = f'Some("{version}")'
    sub = "null" if subtitle is None else str(subtitle)
    out = f'{{"header":{{"version":{v},"patch_version":false,"subtitle":{sub},"date":"{d}"}},"sections":null}}'
    if full:
        return out + "\n\n\n"
    return out

def build_content(fmt, version, subtitle, full):
    d = date.today().isoformat()
    if fmt == "json":
        return json_header(version, subtitle, d, full)
    return markdown_header(version, subtitle, d, full)

def main(argv):
    start = time.monotonic()
    try:
        action, opts = parse_args(argv)
    except CliError as e:
        eprint(str(e))
        return e.code
    if action == "help":
        sys.stdout.write(HELP)
        return 0
    if action == "version":
        sys.stdout.write(VERSION)
        return 0

    try:
        cfg = parse_config(opts.get("config", ".clog.toml"))
    except ValueError:
        return app_error("Failed to parse TOML configuration file")
    except RuntimeError as e:
        return app_error(str(e))

    # Automatic version bumps fail in the observed binary unless an explicit setversion is present.
    if (opts.get("major") or opts.get("minor") or opts.get("patch")) and "setversion" not in opts:
        return app_error("Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.")

    # Config's changelog is a paired default input/output path. CLI infile/outfile override their side.
    cfg_changelog = cfg.get("changelog") if isinstance(cfg.get("changelog"), str) else None
    infile = opts.get("infile") if "infile" in opts else (cfg.get("infile") if isinstance(cfg.get("infile"), str) else cfg_changelog)
    outfile = opts.get("outfile") if "outfile" in opts else (cfg.get("outfile") if isinstance(cfg.get("outfile"), str) else cfg_changelog)
    if "changelog" in opts:
        infile = opts["changelog"]
        outfile = opts["changelog"]

    version = opts.get("setversion")
    subtitle = opts.get("subtitle") if "subtitle" in opts else None
    full = bool(outfile or infile)
    content = build_content(opts.get("format", "markdown"), version, subtitle, full)
    if infile:
        content += read_optional(infile)

    if outfile:
        try:
            with open(outfile, "w", encoding="utf-8") as f:
                f.write(content)
        except Exception:
            return app_error("fatal I/O error with output file")
    else:
        sys.stdout.write(content)

    elapsed = int((time.monotonic() - start) * 1000)
    if elapsed < 2:
        elapsed = 2
    sys.stdout.write(f"changelog written. (took {elapsed} ms)\n")
    return 0

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
